"use strict";(self.webpackChunktik_space=self.webpackChunktik_space||[]).push([["5203"],{36010(e){e.exports=JSON.parse('{"tag":{"label":"Tier 4 \u2014 Production system design","permalink":"/docs/tags/tier-4-system-design","description":"Whole-domain designs where the invariants are the hard part.","allTagsPath":"/docs/tags","count":9,"items":[{"id":"production-patterns/payment-fraud-detection","title":"Fraud Detection","description":"Rule: technically valid is not the same as trustworthy, and blocking too much costs more than","permalink":"/docs/production-patterns/payment-fraud-detection"},{"id":"production-patterns/payment-order-consistency","title":"Order & Payment Consistency","description":"Rule: money moved and the order updated are two facts in two places, and no transaction spans","permalink":"/docs/production-patterns/payment-order-consistency"},{"id":"production-patterns/payment-ledger","title":"Payment Ledger","description":"Rule: payment status says whether a transaction succeeded; only a ledger says where the money","permalink":"/docs/production-patterns/payment-ledger"},{"id":"production-patterns/payment-provider-and-webhooks","title":"Payment Providers & Webhooks","description":"Rule: a provider response and a webhook are external signals, not truth. The only source of","permalink":"/docs/production-patterns/payment-provider-and-webhooks"},{"id":"production-patterns/payment-state-and-idempotency","title":"Payment State & Idempotency","description":"Rule: a payment is a state machine with an idempotency key, never a boolean. paid = true","permalink":"/docs/production-patterns/payment-state-and-idempotency"},{"id":"production-patterns/payment-reconciliation","title":"Reconciliation","description":"Rule: reconciliation is a legitimate source of change, not a silent patch. Every repair it","permalink":"/docs/production-patterns/payment-reconciliation"},{"id":"production-patterns/payment-refunds","title":"Refunds","description":"Rule: a refund is a new transaction, not an undo. It has its own state machine, its own","permalink":"/docs/production-patterns/payment-refunds"},{"id":"production-patterns/payment-settlement","title":"Settlement","description":"Rule: \\"payment succeeded\\" is an intention; settlement is when the money actually arrives.","permalink":"/docs/production-patterns/payment-settlement"},{"id":"interview-prep/system-design-method","title":"System Design Method","description":"Open-ended by construction: \\"design Twitter\\" has no correct answer, and the interviewer is not","permalink":"/docs/interview-prep/system-design-method"}],"unlisted":false}}')}}]);